const cfg = $('SET – Config').first().json;
const rows = ($input.first().json.listings || []);
return rows.map(r => ({ json: { ...r,  crm_base_url: String(cfg.crm_base_url || '').replace(/\/$/, ''), n8n_secret: cfg.n8n_secret } }));

// Field names expected by the production fallback chain.
const l = $json;
return { json: {
  ...l,
  ID: String(l.listing_id),
  lead_key: String(l.listing_id),
  'Isännöitsijä': l.isannoitsija || '',
  'Taloyhtiö': l.taloyhtio || '',
  'Osoite': l.osoite || '',
  'Kaupunki': l.kaupunki || '',
  'IN puh': '',
  'IN email': '',
} };

const j = $json || {};

const isannoitsija = String(j["Isännöitsijä"] || "").trim();
const taloyhtio = String(j["Taloyhtiö"] || "").trim();
const osoite = String(j["Osoite"] || "").trim();
const kaupunki = String(j["Kaupunki"] || "").trim();


const normalizeCompanyName = (name) => {
  return String(name || "")
    .replace(/\byhteystiedot\b/gi, "")
    .replace(/\bisännöitsijä\b/gi, "")
    .replace(/\s{2,}/g, " ")
    .trim();
};

let fallbackQuery = "";
let fallbackTargetType = "";


let finderQuery = "";


let asiakastietoQuery = "";

if (isannoitsija) {
  const cleanName = normalizeCompanyName(isannoitsija);

  fallbackQuery = `${cleanName} ${kaupunki}`.trim();
  finderQuery = cleanName;
  asiakastietoQuery = `${cleanName} ${kaupunki}`.trim();
  fallbackTargetType = "isannoitsija";
} else if (taloyhtio) {
  fallbackQuery = `${taloyhtio} ${osoite} ${kaupunki}`.trim();
  finderQuery = `${taloyhtio}`.trim();
  asiakastietoQuery = `${taloyhtio} ${kaupunki}`.trim();
  fallbackTargetType = "taloyhtio";
} else {
  fallbackQuery = `${osoite} ${kaupunki}`.trim();
  finderQuery = `${osoite}`.trim();
  asiakastietoQuery = `${osoite} ${kaupunki}`.trim();
  fallbackTargetType = "osoite";
}

return {
  json: {
    ...j,
    fallbackPathEntered: true,
    fallbackQuery,
    finderQuery,
    asiakastietoQuery,
    fallbackTargetType,
    fallbackStage: "query_built"
  }
};

const j = $json || {};

const finderQuery = String(j.finderQuery || j.fallbackQuery || "").trim();
const asiakastietoQuery = String(j.asiakastietoQuery || j.fallbackQuery || "").trim();

return {
  json: {
    ...j,
    fallbackStage: "company_search_urls_built",
    companySearchTerm: finderQuery,
    finderSearchUrl: `https://www.finder.fi/search?what=${encodeURIComponent(finderQuery)}`,
    asiakastietoSearchUrl: `https://www.asiakastieto.fi/yritykset/haku?query=${encodeURIComponent(asiakastietoQuery)}`
  }
};

const base = $('TRANSFORM – Build URLs').item.json || {};
const current = $json || {};

const asText = (value) => {
  if (value === undefined || value === null) return "";
  if (typeof value === "string") return value;
  try {
    return JSON.stringify(value);
  } catch (e) {
    return String(value);
  }
};

const html = asText(current.data || current.body || current.response || current);


const noResults =
  /Haullasi ei löytynyt tietoja/i.test(html) ||
  /Kaikki hakutulokset\s*0/i.test(html) ||
  /Yritykset\s*0/i.test(html);

if (noResults) {
  return {
    json: {
      ...base,
      data: current.data || current.body || current.response || "",
      finderCompanyUrl: "",
      finderLinkFound: false,
      finderNoResults: true,
      finderLinkCandidates: [],
      finderSearchHtmlPreview: html.slice(0, 1500)
    }
  };
}


const hrefMatches = [
  ...html.matchAll(/href=["']([^"']+)["']/gi)
].map(m => m[1]);

const candidates = hrefMatches
  .map(href => href.startsWith("http") ? href : `https://www.finder.fi${href}`)
  .filter(url => {
    const u = url.toLowerCase();

    if (!u.startsWith("https://www.finder.fi/")) return false;
    if (u.includes("/search?")) return false;
    if (u.includes("/fonts/")) return false;
    if (u.includes(".css")) return false;
    if (u.includes(".js")) return false;
    if (u.includes(".png")) return false;
    if (u.includes(".jpg")) return false;
    if (u.includes(".jpeg")) return false;
    if (u.includes(".svg")) return false;
    if (u.includes(".webp")) return false;
    if (u.includes("/kartta")) return false;
    if (u.includes("/hakemistot")) return false;

    const path = u.replace("https://www.finder.fi", "");
    const segments = path.split("/").filter(Boolean);


    return segments.length >= 2;
  });

const uniqueCandidates = [...new Set(candidates)];
const finderCompanyUrl = uniqueCandidates[0] || "";

return {
  json: {
    ...base,
    data: current.data || current.body || current.response || "",
    finderCompanyUrl,
    finderLinkFound: !!finderCompanyUrl,
    finderNoResults: false,
    finderLinkCandidates: uniqueCandidates.slice(0, 10),
    finderSearchHtmlPreview: html.slice(0, 1500)
  }
};

const base = $('TRANSFORM – Build URLs').item.json || {};
const current = $json || {};

const asText = (value) => {
  if (value === undefined || value === null) return "";
  if (typeof value === "string") return value;
  try {
    return JSON.stringify(value);
  } catch (e) {
    return String(value);
  }
};

const finderRaw = asText(
  current.data || current.body || current.response || current
);

return {
  json: {
    ...base,
    finderRaw,
    debug_storeFinder: {
      keys: Object.keys(current || {}),
      hasData: !!current.data,
      hasBody: !!current.body,
      preview: finderRaw.slice(0, 1000)
    }
  }
};

const base = $('STORE – Save Finder Response').item.json || {};
const current = $json || {};

const asText = (value) => {
  if (value === undefined || value === null) return "";
  if (typeof value === "string") return value;
  try {
    return JSON.stringify(value);
  } catch (e) {
    return String(value);
  }
};

const html = asText(current.data || current.body || current.response || current);

const noResults =
  /Hakusi ei tuottanut tuloksia/i.test(html) ||
  /Ei hakutuloksia/i.test(html);

if (noResults) {
  return {
    json: {
      ...base,
      asiakastietoCompanyUrl: "",
      asiakastietoLinkFound: false,
      asiakastietoNoResults: true,
      asiakastietoLinkCandidates: [],
      asiakastietoSearchHtmlPreview: html.slice(0, 1500)
    }
  };
}

const hrefMatches = [
  ...html.matchAll(/href=["']([^"']+)["']/gi)
].map(m => m[1]);

const toAbsoluteUrl = (href) => {
  if (!href) return "";
  if (href.startsWith("http")) return href;
  if (href.startsWith("/")) return `https://www.asiakastieto.fi${href}`;
  return "";
};

const isValidCompanyPage = (url) => {
  const u = String(url || "").toLowerCase().trim();
  if (!u.startsWith("https://www.asiakastieto.fi/")) return false;

  const blockedPatterns = [
    "/web/fi/",
    "/web/en/",
    "/opensso/",
    "/yritykset/haku",
    "/yritykset/unohtuiko-salasana",
    "/yritykset/rekisteroidy",
    "/yritykset/tuotteet-ja-palvelut",
    "/asiakastieto-yrityksena/",
    "/palvelut-yrityksille/",
    "/verkkokauppa/",
    "/kuluttajille/",
    "/kiinteisto-ja-huoneistotiedot/",
    "/media/",
    ".css",
    ".js",
    ".png",
    ".jpg",
    ".jpeg",
    ".svg",
    ".webp"
  ];

  if (blockedPatterns.some(p => u.includes(p))) return false;


  if (!u.includes("/yritykset/")) return false;

  const path = u.replace("https://www.asiakastieto.fi", "");
  const segments = path.split("/").filter(Boolean);


  if (segments.length < 4) return false;

  return true;
};

const candidates = hrefMatches
  .map(toAbsoluteUrl)
  .filter(Boolean)
  .filter(isValidCompanyPage);

const uniqueCandidates = [...new Set(candidates)];
const asiakastietoCompanyUrl = uniqueCandidates[0] || "";

return {
  json: {
    ...base,
    asiakastietoCompanyUrl,
    asiakastietoLinkFound: !!asiakastietoCompanyUrl,
    asiakastietoNoResults: false,
    asiakastietoLinkCandidates: uniqueCandidates.slice(0, 10),
    asiakastietoSearchHtmlPreview: html.slice(0, 1500)
  }
};

const base = $('STORE – Save Finder Response').item.json || {};
const current = $json || {};

const asText = (value) => {
  if (value === undefined || value === null) return "";
  if (typeof value === "string") return value;
  if (typeof value === "object") {
    try {
      return JSON.stringify(value);
    } catch (e) {
      return String(value);
    }
  }
  return String(value);
};

const unique = (arr) => {
  return [...new Set(arr.map(v => String(v).trim()).filter(Boolean))];
};

const cleanPhone = (phone) => {
  if (!phone) return "";
  return String(phone)
    .replace(/\s+/g, " ")
    .replace(/[^\d+ ]/g, "")
    .trim();
};

const LIMIT = 30000;

const finderRaw = asText(
  base.finderRaw || base.body || base.data || base.response || ""
).slice(0, LIMIT);

const asiakastietoRaw = asText(
  current.data || current.body || current.response || current
).slice(0, LIMIT);

const combinedSearchText = [finderRaw, asiakastietoRaw]
  .filter(Boolean)
  .join("\n\n---SOURCE_BREAK---\n\n");


const emailMatches =
  combinedSearchText.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [];

const emails = unique(
  emailMatches.filter(email => {
    const e = email.toLowerCase();
    if (e.includes("finder.fi")) return false;
    if (e.includes("asiakastieto.fi")) return false;
    return true;
  })
);


const websiteMatches =
  combinedSearchText.match(/https?:\/\/[^\s"'<>]+/gi) || [];

const badWebsitePatterns = [
  "finder.fi",
  "asiakastieto.fi",
  "ucarecdn",
  "googletagmanager",
  "google-analytics",
  "doubleclick",
  "facebook.com",
  "fbcdn",
  "instagram.com",
  "linkedin.com",
  "youtube.com",
  "connect.facebook.net",
  "fonts.googleapis.com",
  "fonts.gstatic.com",
  "code.jquery.com",
  "cdnjs.cloudflare.com",
  "maxcdn.bootstrapcdn.com",
  "service.giosg.com",
  "track.adform.net",
  "google.com",
  "google.fi",
  "w3.org",
  "upseller.cloud",
  "enento.com/sijoittajat",
  ".js",
  ".css",
  ".svg",
  ".png",
  ".jpg",
  ".jpeg",
  ".webp",
  "cookie",
  "consent"
];

const websites = unique(
  websiteMatches.filter(url => {
    const u = String(url || "").toLowerCase();
    if (!u) return false;
    if (badWebsitePatterns.some(x => u.includes(x))) return false;
    return true;
  })
);

// PUHELIMET yleisesti
const allPhoneMatches =
  combinedSearchText.match(/(?:\+358|0)\d(?:[\d ]{5,20}\d)/g) || [];

const allPhones = unique(
  allPhoneMatches
    .map(p => cleanPhone(p))
    .filter(p => {
      const digits = p.replace(/\D/g, "");
      return digits.length >= 8 && digits.length <= 15;
    })
);

let finderPrimaryPhone = "";
const finderLabelMatch =
  finderRaw.match(/Puhelin(?:numero)?[\s\S]{0,250}?((?:\+358|0)\d(?:[\d ]{5,20}\d))/i) ||
  finderRaw.match(/Soita[\s\S]{0,120}?((?:\+358|0)\d(?:[\d ]{5,20}\d))/i);

if (finderLabelMatch) {
  finderPrimaryPhone = cleanPhone(finderLabelMatch[1]);
}

let asiakastietoPrimaryPhone = "";
const asiakastietoLabelMatch =
  asiakastietoRaw.match(/Puhelin(?:numero)?[\s\S]{0,250}?((?:\+358|0)\d(?:[\d ]{5,20}\d))/i);

if (asiakastietoLabelMatch) {
  asiakastietoPrimaryPhone = cleanPhone(asiakastietoLabelMatch[1]);
}

const fallbackCandidatePhones = unique([
  asiakastietoPrimaryPhone,
  finderPrimaryPhone,
  ...allPhones
].filter(Boolean));

const fallbackPrimaryPhone =
  asiakastietoPrimaryPhone ||
  finderPrimaryPhone ||
  fallbackCandidatePhones[0] ||
  "";

const fallbackPrimaryWebsite = websites[0] || "";

let fallbackSourceHint = "";
if (asiakastietoRaw.trim() && (asiakastietoPrimaryPhone || emails.length || websites.length)) {
  fallbackSourceHint = "asiakastieto";
} else if (finderRaw.trim() && (finderPrimaryPhone || emails.length || websites.length)) {
  fallbackSourceHint = "finder";
} else if (finderRaw.trim()) {
  fallbackSourceHint = "finder";
}

const foundSomething =
  emails.length > 0 ||
  fallbackCandidatePhones.length > 0 ||
  websites.length > 0;

return {
  json: {
    ...base,
    fallbackStage: "company_search_responses_parsed",
    finderRaw,
    asiakastietoRaw,
    finderRawPreview: finderRaw.slice(0, 1500),
    asiakastietoRawPreview: asiakastietoRaw.slice(0, 1500),
    combinedSearchText: combinedSearchText.slice(0, 6000),

    finderPrimaryPhone,
    asiakastietoPrimaryPhone,

    debug_raw_keys: {
      baseKeys: Object.keys(base || {}),
      currentKeys: Object.keys(current || {})
    },

    fallbackCandidateEmails: emails,
    fallbackCandidatePhones,
    fallbackCandidateWebsites: websites,
    fallbackPrimaryPhone,
    fallbackPrimaryWebsite,
    fallbackSourceHint,
    fallbackFoundSomething: foundSomething
  }
};

const j = $json || {};

const rawPhones = Array.isArray(j.fallbackCandidatePhones) ? j.fallbackCandidatePhones : [];
const rawWebsites = Array.isArray(j.fallbackCandidateWebsites) ? j.fallbackCandidateWebsites : [];

const blacklistDomains = [
  "schema.org",
  "ogp.me",
  "twitter.com",
  "facebook.com",
  "instagram.com",
  "linkedin.com",
  "youtube.com",
  "youtu.be",
  "adx.adform.net",
  "google.com",
  "googletagmanager.com",
  "doubleclick.net",
  "gstatic.com",
  "tiktok.com"
];

function normalizePhone(phone) {
  if (!phone) return "";
  return String(phone)
    .replace(/[^\d+]/g, "")
    .trim();
}

function isValidPhone(phone) {
  const p = normalizePhone(phone);
  if (!p) return false;
  const digits = p.replace(/\D/g, "");
  return digits.length >= 6;
}

function normalizeWebsite(url) {
  if (!url) return "";
  return String(url).trim();
}

function isGoodWebsite(url) {
  if (!url) return false;

  const lower = url.toLowerCase();

  if (!lower.startsWith("http")) return false;

  return !blacklistDomains.some(domain => lower.includes(domain));
}

const cleanedPhones = [...new Set(
  rawPhones
    .map(normalizePhone)
    .filter(isValidPhone)
)];

const cleanedWebsites = [...new Set(
  rawWebsites
    .map(normalizeWebsite)
    .filter(isGoodWebsite)
)];

const primaryPhone =
  normalizePhone(j.fallbackPrimaryPhone) ||
  cleanedPhones[0] ||
  "";

const primaryWebsite =
  isGoodWebsite(j.fallbackPrimaryWebsite)
    ? j.fallbackPrimaryWebsite
    : (cleanedWebsites[0] || "");

return {
  json: {
    ...j,
    fallbackCandidatePhones: cleanedPhones,
    fallbackCandidateWebsites: cleanedWebsites,
    fallbackPrimaryPhone: primaryPhone,
    fallbackPrimaryWebsite: primaryWebsite,
    fallbackFoundSomething: cleanedPhones.length > 0 || cleanedWebsites.length > 0
  }
};

